PROGRAM airlock
VAR_INPUT
    OpenA_Cmd : BOOL;
    OpenB_Cmd : BOOL;
END_VAR
VAR_OUTPUT
    DoorA : BOOL;
    DoorB : BOOL;
END_VAR
VAR
    T1 : TON;
END_VAR

T1(IN := OpenA_Cmd AND NOT DoorA);

IF OpenA_Cmd AND NOT OpenB_Cmd THEN
    DoorA := TRUE;
ELSIF OpenB_Cmd AND NOT T1.Q THEN
    DoorA := FALSE;
ELSE
    DoorA := FALSE;
END_IF;

IF OpenB_Cmd AND NOT T1.Q THEN
    DoorB := TRUE;
ELSE
    DoorB := FALSE;
END_IF;

END_PROGRAM

