PROGRAM alarm_ctrl
VAR_INPUT
    Trip : BOOL;
    Reset : BOOL;
END_VAR
VAR_OUTPUT
    Alarm : BOOL;
END_VAR
VAR
    Latch : BOOL;
END_VAR

IF Trip AND NOT Reset THEN
    Latch := TRUE;
ELSIF NOT Trip AND Reset THEN
    Latch := FALSE;
END_IF;

Alarm := Latch AND Trip;

END_PROGRAM

PROGRAM alarm_ctrl
VAR_INPUT
    Trip : BOOL;
    Reset : BOOL;
END_VAR
VAR_OUTPUT
    Alarm : BOOL;
END_VAR
VAR
    Latched : BOOL;
END_VAR
VAR CONSTANT
    TRIP_HOLD_TIME : TIME := T#5s;
END_VAR

