    Latched := TRUE;
ELSIF Trip AND NOT Reset THEN
    Latched := TRUE;
ELSIF NOT Trip AND Reset AND Latched THEN
    Latched := FALSE;
END_IF;

Alarm := Latched;

END_PROGRAM

