        IF CallUp AND DoorClosed THEN
            State := UP;
        ELSIF Not DoorClosed THEN
            MotorUp := FALSE;
            MotorDown := FALSE;
        END_IF;

    UP:
        IF AtTop OR (CallDown AND DoorClosed) THEN
            State := TOP;
        ELSIF Not DoorClosed THEN
            MotorUp := FALSE;
            MotorDown := FALSE;
        END_IF;

    TOP:
        IF CallDown AND DoorClosed THEN
            State := DOWN;
        ELSIF Not DoorClosed THEN
            MotorUp := FALSE;
            MotorDown := FALSE;
        END_IF;

    DOWN:
        IF AtBottom OR (CallUp AND DoorClosed) THEN
            State := BOTTOM;
        ELSIF Not DoorClosed THEN
            MotorUp := FALSE;
            MotorDown := FALSE;
        END_IF;
END_CASE;

CASE State OF
    BOTTOM:
        MotorUp := TRUE;
        MotorDown := FALSE;
    UP:
        MotorUp := TRUE;
        MotorDown := FALSE;
    TOP:
        MotorUp := FALSE;
        MotorDown := TRUE;
    DOWN:
        MotorUp := FALSE;
        MotorDown := TRUE;
