    Temp : INT;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR
VAR
    State : INT;
END_VAR
VAR CONSTANT
    LIQ_MIN : INT := 10;
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    TEMP_SET : INT := 100;
    PT_REACT : TIME literal := T#3s;
END_VAR

CASE EStop OF
    FALSE:
        State := 0;
END_CASE;

CASE State OF
    0:  // Idle
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
        IF StartBatch AND EStop THEN
            State := 1;
        END_IF;

    1:  // Fill
        FillValve := TRUE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
        IF Level >= LVL_HIGH OR NOT EStop THEN
            State := 2;
        END_IF;

    2:  // Heat
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;
        IF Level < LIQ_MIN OR NOT EStop THEN
            State := 0;
        ELSIF Temp >= TEMP_SET THEN
            State := 3;
        END_IF;

    3:  // React
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;
        IF Level < LIQ_MIN OR NOT EStop THEN
            State := 0;
        ELSIF T#3s.TICKCOUNT >= PT_REACT THEN
            State := 4;
        END_IF;

    4:  // Drain
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := TRUE;
        IF Level <= LVL_LOW OR NOT EStop THEN
            State := 0;
        END_IF;
END_CASE;

END_PROGRAM

