    PT_REACT : TIME literal := T#3s;
END_VAR
VAR_TON
    T1;
END_VAR

T1(IN := EStop OR (State >= 1 AND State <= 4 AND Level < LIQ_MIN) OR (State = 4 AND Level >= LVL_LOW), PT := PT_REACT);

CASE State OF
    0:
        IF StartBatch AND EStop THEN
            State := 1;
        END_IF;
    1:
        IF T1.Q OR Level >= LVL_HIGH THEN
            State := 2;
        END_IF;
        FillValve := TRUE;
    2:
        IF T1.Q OR Temp >= TEMP_SET THEN
            State := 3;
        END_IF;
        Heater := TRUE;
        Agitator := TRUE;
    3:
        IF T1.Q AND TimeTicks >= PT_REACT.TICKS THEN
            State := 4;
        ELSIF NOT EStop THEN
            State := 0;
        END_IF;
        Heater := TRUE;
        Agitator := TRUE;
    4:
        IF T1.Q OR Level <= LVL_LOW THEN
            State := 0;
        END_IF;
        DrainValve := TRUE;
END_CASE;

END_PROGRAM

PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR
VAR
    State : INT;
END_VAR
VAR CONSTANT
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    LIQ_MIN : INT := 10;
    TEMP_SET : INT := 100;
    PT_REACT : TIME literal := T#3s;
END_VAR

CASE EStop OF
    FALSE:
        State := 0;
END_CASE;

CASE State OF
    0: // Idle
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
        IF StartBatch AND EStop THEN
            State := 1;
        END_IF;

    1: // Fill
        FillValve := TRUE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
        IF Level >= LVL_HIGH OR NOT EStop THEN
            State := 2;
        END_IF;

    2: // Heat
        FillValve := FALSE;
        Heater := Level >= LIQ_MIN;
        Agitator := Level >= LIQ_MIN;
        DrainValve := FALSE;
        IF (NOT Level >= LIQ_MIN) OR Temp >= TEMP_SET OR NOT EStop THEN
            State := 2;
        ELSIF Temp >= TEMP_SET THEN
            State := 3;
        END_IF;

    3: // React
        FillValve := FALSE;
        Heater := Level >= LIQ_MIN;
        Agitator := Level >= LIQ_MIN;
        DrainValve := FALSE;
        IF (NOT Level >= LIQ_MIN) OR NOT EStop OR T#0s.TICKS >= PT_REACT.Ticks THEN
            State := 4;
        END_IF;

    4: // Drain
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := Level >= LVL_LOW;
        IF Level <= LVL_LOW OR NOT EStop THEN
            State := 0;
        END_IF;
END_CASE;

END_PROGRAM

PROGRAM garage
