PROGRAM tank_cycle
VAR_INPUT
    Level : INT;
    StartCycle : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    Pump : BOOL;
    Valve : BOOL;
END_VAR
VAR
    State : INT;
END_VAR
VAR CONSTANT
    IDLE : INT := 0;
    FILLING : INT := 1;
    DRAINING : INT := 2;
    HI_LEVEL : INT := 90;
    LO_LEVEL : INT := 10;
END_VAR

IF NOT EStop THEN
    State := IDLE;
ELSIF EStop AND (State = FILLING OR State = DRAINING) THEN
    State := IDLE;
ELSIF EStop AND State = IDLE AND StartCycle AND Level < HI_LEVEL THEN
    State := FILLING;
ELSIF EStop AND State = FILLING AND Level >= HI_LEVEL THEN
    State := DRAINING;
ELSIF EStop AND State = DRAINING AND Level <= LO_LEVEL THEN
    State := IDLE;
END_IF;

CASE State OF
    IDLE:
        Pump := FALSE;
        Valve := FALSE;
    FILLING:
        Pump := TRUE;
        Valve := FALSE;
    DRAINING:
        Pump := FALSE;
        Valve := TRUE;
END_CASE;

END_PROGRAM

PROGRAM tank_cycle
VAR_INPUT
    Level : INT;
    StartCycle : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    Pump : BOOL;
    Valve : BOOL;
END_VAR
VAR
    State : INT;
END_VAR
VAR CONSTANT
    HI_LEVEL : INT := 90;
    LO_LEVEL : INT := 10;
END_VAR

IF NOT EStop THEN
    State := 0;
ELSIF Level >= HI_LEVEL AND State <> 1 THEN
    State := 1;
ELSIF Level <= LO_LEVEL AND State <> 2 THEN
    State := 2;
ELSIF StartCycle AND Level < HI_LEVEL AND State = 0 THEN
    State := 1;
END_IF;

CASE State OF
    0:  // Idle
        Pump := FALSE;
        Valve := FALSE;
    1:  // Filling
        Pump := TRUE;
        Valve := FALSE;
    2:  // Draining
        Pump := FALSE;
        Valve := TRUE;
END_CASE;

END_PROGRAM

