    LO_LEVEL : INT := 10;
END_VAR

IF NOT EStop THEN
    State := 0;
ELSIF EStop AND (Level >= HI_LEVEL) THEN
    State := 2;
ELSIF EStop AND (Level <= LO_LEVEL) THEN
    State := 0;
ELSIF StartCycle AND (Level < HI_LEVEL) AND (State = 0) THEN
    State := 1;
END_IF;

CASE State OF
    0:  // Idle
        Pump := FALSE;
        Valve := FALSE;
    1:  // Filling
        Pump := TRUE;
