VAR CONSTANT
    IDLE : INT := 0;
    FILLING : INT := 1;
    DRAINING : INT := 2;
    HIGH : INT := 90;
    LOW : INT := 10;
END_VAR

IF NOT EStop THEN
    State := IDLE;
ELSIF EStop AND (Level >= HIGH OR Level <= LOW) AND StartCycle THEN
    State := FILLING
ELSIF EStop AND Level > LOW AND Level < HIGH AND StartCycle THEN
    State := DRAINING
ELSIF EStop AND Level >= HIGH AND StartCycle THEN
    State := DRAINING
ELSIF EStop AND Level <= LOW AND StartCycle THEN
    State := FILLING
END_IF;

