    EStop : BOOL;
    Flame : BOOL;
END_VAR
VAR_OUTPUT
    Fan : BOOL;
    Fuel : BOOL;
    Ignition : BOOL;
END_VAR
VAR
    State : INT;
END_VAR
VAR CONSTANT
