    PT_IGN : TIME := T#2s;
END_VAR

CASE State OF
    0:  // Off
        IF (NOT EStop) OR StopPB OR StartPB THEN
            State := 0;
        ELSIF EStop AND StartPB THEN
            State := 1;
        END_IF;
        Fan := FALSE;
        Fuel := FALSE;
        Ignition := FALSE;

    1:  // Purge
        IF (NOT EStop) OR StopPB OR NOT EStop THEN
            State := 0;
        ELSIF TimeCount >= PT_PURGE.Ticks THEN
            State := 2;
        END_IF;
        Fan := TRUE;
        Fuel := FALSE;
        Ignition := FALSE;

    2:  // Ignite
        IF (NOT EStop) OR StopPB OR NOT EStop OR (TimeCount >= PT_IGN.Ticks AND NOT Flame) THEN
            State := 0;
        ELSIF EStop AND TimeCount >= PT_IGN.Ticks AND Flame THEN
            State := 3;
        END_IF;
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := (TimeCount < PT_IGN.Ticks);

    3:  // Run
        IF (NOT EStop) OR StopPB OR NOT EStop OR NOT Flame THEN
            State := 0;
        END_IF;
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := FALSE;

END_CASE;

