VAR_INPUT
    Demand : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    Pump1 : BOOL;
    Pump2 : BOOL;
END_VAR
VAR
    Lead : INT;
    PrevDemand : BOOL;
END_VAR
VAR CONSTANT
    PUMP_OFF : BOOL := FALSE;
    PUMP_ON : BOOL := TRUE;
END_VAR

IF NOT EStop THEN
    Lead := 0;
ELSIF Demand AND NOT PrevDemand THEN
    Lead := 1 - Lead;
END_IF;

Pump1 := Demand AND EStop AND (Lead = 0);
Pump2 := Demand AND EStop AND (Lead = 1);

PrevDemand := Demand;

END_PROGRAM

PROGRAM pump_alt
VAR_INPUT
    Demand : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    Pump1 : BOOL;
    Pump2 : BOOL;
END_VAR
VAR
    Lead : INT;
    PrevDemand : BOOL;
END_VAR
VAR CONSTANT
    PUMP_OFF : TON;
    PUMP_ON : TON;
END_VAR

PUMP_OFF.ET := T#0s;
PUMP_ON.ET := T#0s;

IF NOT EStop THEN
    Lead := 0;
    Pump1 := FALSE;
    Pump2 := FALSE;
ELSIF Demand AND NOT PrevDemand THEN
    Lead := 1 - Lead;
ELSIF Demand THEN
    CASE Lead OF
        0: Pump1 := TRUE; Pump2 := FALSE;
        1: Pump1 := FALSE; Pump2 := TRUE;
    ELSE
        Pump1 := FALSE; Pump2 := FALSE;
    END_CASE;
END_IF;

PrevDemand := Demand;

END_PROGRAM

