VAR
    State : INT;
END_VAR
VAR CONSTANT
    IDLE : INT := 0;
    OPENING : INT := 1;
    CLOSING : INT := 2;
END_VAR

CASE State OF
    IDLE:
        MotorOpen := FALSE;
        MotorClose := FALSE;
        IF CloseCmd AND NOT CloseLimit AND NOT Obstruction THEN
            State := CLOSING;
        ELSIF OpenCmd AND NOT OpenLimit THEN
            State := OPENING;
        END_IF;

    OPENING:
        MotorOpen := TRUE;
        MotorClose := FALSE;
        IF OpenLimit OR Obstruction THEN
            State := IDLE;
        ELSIF CloseCmd AND NOT CloseLimit AND NOT Obstruction THEN
            State := CLOSING;
        END_IF;

    CLOSING:
        MotorOpen := FALSE;
        MotorClose := TRUE;
        IF CloseLimit OR Obstruction THEN
            State := IDLE;
        ELSIF OpenCmd AND NOT OpenLimit THEN
            State := OPENING;
        END_IF;
END_CASE;

END_PROGRAM

