PROGRAM conveyor3
VAR_INPUT
    StartPB : BOOL;
    StopPB  : BOOL;
    EStop   : BOOL;
END_VAR
VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR
VAR
    State : INT;
END_VAR
VAR CONSTANT
    PT_SEQ : TIME := T#2s;
END_VAR

CASE State OF
    0:
        C1 := FALSE;
        C2 := FALSE;
        C3 := FALSE;
        IF EStop THEN
            State := 0;
        ELSIF StartPB AND NOT StopPB THEN
            State := 1;
        END_IF;

    1:
        C1 := FALSE;
        C2 := FALSE;
        C3 := TRUE;
        IF NOT EStop THEN
            State := 0;
        ELSIF StartPB AND NOT StopPB AND State = 1 THEN
            State := 2;
        END_IF;

    2:
        C1 := FALSE;
        C2 := TRUE;
        C3 := TRUE;
        IF NOT EStop THEN
            State := 0;
        ELSIF StartPB AND NOT StopPB AND State = 2 THEN
            State := 3;
        END_IF;

    3:
        C1 := TRUE;
        C2 := TRUE;
        C3 := TRUE;
        IF NOT EStop THEN
            State := 0;
